import metadata from './block.json';

const { attributes: blockAttributes, supports: blockSupports } = metadata;

type ImageAttributes = Record< string, unknown > & {
	width?: number | string;
	height?: number | string;
	behaviors?: { lightbox?: { enabled?: boolean } };
	lightbox?: { enabled?: boolean };
};

/**
 * Deprecation for the `behaviors` attribute, replaced by `lightbox`.
 *
 * Attribute-only: the markup of that version is regenerated by the parser.
 *
 * @see https://github.com/WordPress/gutenberg/pull/53851
 */
const v8 = {
	attributes: {
		...blockAttributes,
		behaviors: {
			type: 'object',
		},
	},
	supports: blockSupports,
	isEligible( attributes: ImageAttributes ) {
		return !! attributes.behaviors;
	},
	migrate( { width, height, ...attributes }: ImageAttributes ) {
		// We need to perform a check here because in cases
		// where attributes are added dynamically to blocks,
		// block invalidation overrides the isEligible() method
		// and forces the migration to run, so it's not guaranteed
		// that `behaviors` or `behaviors.lightbox` will be defined.
		if ( ! attributes.behaviors?.lightbox ) {
			return attributes;
		}
		const { enabled } = attributes.behaviors.lightbox;
		const newAttributes = {
			...attributes,
			lightbox: {
				enabled,
			},
		};
		delete newAttributes.behaviors;
		return newAttributes;
	},
};

/**
 * Deprecation for the numeric `width` and `height` attributes, stored as a
 * number of pixels until the block switched to string values with units.
 *
 * Attribute-only: the markup of those versions (responsive and `is-resized`
 * classes, the align wrapper, size attributes on the `img`) is regenerated by
 * the parser; only the sizes need migrating.
 *
 * @see https://github.com/WordPress/gutenberg/pull/31366
 * @see https://github.com/WordPress/gutenberg/pull/52081
 */
const numericSizes = {
	attributes: {
		...blockAttributes,
		width: {
			type: 'number',
		},
		height: {
			type: 'number',
		},
	},
	supports: blockSupports,
	isEligible( { width, height }: ImageAttributes ) {
		return typeof width === 'number' || typeof height === 'number';
	},
	migrate( attributes: ImageAttributes ) {
		const { width, height } = attributes;
		return {
			...attributes,
			width: typeof width === 'number' ? `${ width }px` : width,
			height: typeof height === 'number' ? `${ height }px` : height,
		};
	},
};

export default [ v8, numericSizes ];
